import java.util.ArrayList;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Optional;

/**
 * A self-balancing AVL binary search tree.
 *
 * <p>The tree keeps its height in O(log n) by re-balancing with rotations after
 * every modification, guaranteeing O(log n) {@link #insert}, {@link #remove}
 * and {@link #contains}. Elements are ordered either by their natural ordering
 * ({@link Comparable}) or by a {@link Comparator} supplied at construction.
 *
 * <p>Duplicate elements are not stored; {@link #insert} reports whether the
 * element was actually added. In-order iteration yields elements in sorted
 * order.
 *
 * @param <T> the type of elements held in the tree
 */
class AVLTree<T> implements Iterable<T> {

    /** An immutable-shaped node; structure is mutated only by the tree itself. */
    private static final class Node<T> {
        T value;
        Node<T> left;
        Node<T> right;
        int height = 1;

        Node(T value) {
            this.value = value;
        }
    }

    private final Comparator<? super T> comparator;
    private Node<T> root;
    private int size;

    /** Creates a tree that orders elements by their natural ordering. */
    AVLTree() {
        this.comparator = null;
    }

    /**
     * Creates a tree that orders elements with the given comparator.
     *
     * @param comparator the ordering to use; must not be {@code null}
     */
    AVLTree(Comparator<? super T> comparator) {
        if (comparator == null) {
            throw new NullPointerException("comparator");
        }
        this.comparator = comparator;
    }

    // ---------------------------------------------------------------------
    // Public API
    // ---------------------------------------------------------------------

    /**
     * Inserts {@code value} into the tree, keeping it balanced.
     *
     * @param value the element to add; must not be {@code null}
     * @return {@code true} if the element was added, {@code false} if an equal
     *         element was already present
     */
    boolean insert(T value) {
        if (value == null) {
            throw new NullPointerException("value");
        }
        int sizeBefore = size;
        root = insert(root, value);
        return size != sizeBefore;
    }

    /**
     * Removes the element equal to {@code value}, keeping the tree balanced.
     *
     * @param value the element to remove; must not be {@code null}
     * @return {@code true} if an element was removed, {@code false} if no equal
     *         element was present
     */
    boolean remove(T value) {
        if (value == null) {
            throw new NullPointerException("value");
        }
        int sizeBefore = size;
        root = remove(root, value);
        return size != sizeBefore;
    }

    /**
     * Returns whether an element equal to {@code value} is present.
     *
     * @param value the element to look for; must not be {@code null}
     */
    boolean contains(T value) {
        if (value == null) {
            throw new NullPointerException("value");
        }
        Node<T> current = root;
        while (current != null) {
            int cmp = compare(value, current.value);
            if (cmp < 0) {
                current = current.left;
            } else if (cmp > 0) {
                current = current.right;
            } else {
                return true;
            }
        }
        return false;
    }

    /** Returns the number of elements in the tree. */
    int size() {
        return size;
    }

    /** Returns whether the tree contains no elements. */
    boolean isEmpty() {
        return size == 0;
    }

    /** Returns the height of the tree (0 for an empty tree). */
    int height() {
        return height(root);
    }

    /** Removes all elements from the tree. */
    void clear() {
        root = null;
        size = 0;
    }

    /** Returns the elements in ascending (sorted) order. */
    List<T> inOrder() {
        List<T> out = new ArrayList<>(size);
        inOrder(root, out);
        return out;
    }

    /** Returns the elements in pre-order (root, left subtree, right subtree). */
    List<T> preOrder() {
        List<T> out = new ArrayList<>(size);
        preOrder(root, out);
        return out;
    }

    /** Iterates over the elements in ascending (sorted) order. */
    @Override
    public Iterator<T> iterator() {
        return inOrder().iterator();
    }

    // ---------------------------------------------------------------------
    // Insertion and balancing
    // ---------------------------------------------------------------------

    private Node<T> insert(Node<T> node, T value) {
        if (node == null) {
            size++;
            return new Node<>(value);
        }

        int cmp = compare(value, node.value);
        if (cmp < 0) {
            node.left = insert(node.left, value);
        } else if (cmp > 0) {
            node.right = insert(node.right, value);
        } else {
            return node; // duplicate: no change
        }

        updateHeight(node);
        return rebalance(node);
    }

    /** Restores the AVL invariant at {@code node} with at most two rotations. */
    private Node<T> rebalance(Node<T> node) {
        int balance = balanceFactor(node);

        // Left-heavy
        if (balance > 1) {
            if (balanceFactor(node.left) < 0) {
                node.left = rotateLeft(node.left); // Left-Right case
            }
            return rotateRight(node); // Left-Left case
        }

        // Right-heavy
        if (balance < -1) {
            if (balanceFactor(node.right) > 0) {
                node.right = rotateRight(node.right); // Right-Left case
            }
            return rotateLeft(node); // Right-Right case
        }

        return node; // already balanced
    }

    private Node<T> rotateRight(Node<T> y) {
        Node<T> x = y.left;
        y.left = x.right;
        x.right = y;
        updateHeight(y);
        updateHeight(x);
        return x;
    }

    private Node<T> rotateLeft(Node<T> x) {
        Node<T> y = x.right;
        x.right = y.left;
        y.left = x;
        updateHeight(x);
        updateHeight(y);
        return y;
    }

    // ---------------------------------------------------------------------
    // Traversals
    // ---------------------------------------------------------------------

    private void inOrder(Node<T> node, List<T> out) {
        if (node != null) {
            inOrder(node.left, out);
            out.add(node.value);
            inOrder(node.right, out);
        }
    }

    private void preOrder(Node<T> node, List<T> out) {
        if (node != null) {
            out.add(node.value);
            preOrder(node.left, out);
            preOrder(node.right, out);
        }
    }

    // ---------------------------------------------------------------------
    // Height / balance helpers
    // ---------------------------------------------------------------------

    private static int height(Node<?> node) {
        return node == null ? 0 : node.height;
    }

    private static void updateHeight(Node<?> node) {
        node.height = 1 + Math.max(height(node.left), height(node.right));
    }

    private static int balanceFactor(Node<?> node) {
        return node == null ? 0 : height(node.left) - height(node.right);
    }

    @SuppressWarnings("unchecked")
    private int compare(T a, T b) {
        if (comparator != null) {
            return comparator.compare(a, b);
        }
        return ((Comparable<? super T>) a).compareTo(b);
    }
}

